using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class SlabFormatGroup {public string Mark;public List<SlabScheduleRow> Source=new List<SlabScheduleRow>();public SlabScheduleRow Schedule{get{return Source[0];}}public string Originals{get{return string.Join(", ",Source.Select(s=>s.Mark));}}}
class SlabFormatResult {public Dxf Drawing;public List<SlabFormatGroup> Groups;public int SourceCount;}
static class SlabFormatter {
 internal static string Plain(Entity e){string text=string.Concat(e.P.Where(p=>p.Code==1||p.Code==3).Select(p=>p.Value));text=Regex.Replace(text,@"\\[fFHWAQ][^;]*;","");return text.Replace("{","").Replace("}","").Replace("\\P"," ").Trim();}
 internal static string Signature(SlabScheduleRow row){return row.Thickness.ToString("R",CultureInfo.InvariantCulture)+"|"+string.Join("|",row.Bars.Select(b=>b==null?"--":b.Diameter+"@"+b.SpacingMm.ToString("R",CultureInfo.InvariantCulture)));}
 public static List<SlabFormatGroup> Group(IEnumerable<SlabScheduleRow> rows,string prefix,bool merge){prefix=(prefix??"").Trim().ToUpperInvariant();if(!Regex.IsMatch(prefix,@"^[A-Z0-9]*S$")||prefix.Length>12)throw new Exception("Enter slab prefix, e.g. 2S for Second Floor.");var groups=new List<SlabFormatGroup>();var lookup=new Dictionary<string,SlabFormatGroup>();var marks=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in rows){if(!marks.Add(row.Mark))throw new Exception("Duplicate slab mark: "+row.Mark);string key=Signature(row);SlabFormatGroup group;if(!merge||!lookup.TryGetValue(key,out group)){group=new SlabFormatGroup();groups.Add(group);lookup[key]=group;}group.Source.Add(row);}for(int n=0;n<groups.Count;n++)groups[n].Mark=prefix+"-"+(n+1).ToString("000");return groups;}
 public static string BarText(SlabBar bar){return bar==null?"--":"%%C"+bar.Diameter+" @ "+bar.SpacingMm.ToString("0.##",CultureInfo.InvariantCulture)+"mm C/C";}
 public static SlabFormatResult Build(string raw,string prefix,string floor,bool merge){if(string.IsNullOrWhiteSpace(floor))throw new Exception("Enter floor title.");var source=SlabScheduleReader.Read(raw);var groups=Group(source,prefix,merge);if(groups.Count==0)throw new Exception("No slab rows to format.");Dxf drawing;using(var stream=typeof(SlabFormatter).Assembly.GetManifestResourceStream("SlabTemplate.dxf")){if(stream==null)throw new Exception("Slab template resource missing.");using(var reader=new StreamReader(stream,Encoding.UTF8,true))drawing=Dxf.Parse(reader.ReadToEnd());}
 var original=drawing.ModelEntities();var title=original.FirstOrDefault(e=>e.Type=="MTEXT"&&Plain(e)=="SCHEDULE OF SLAB");if(title==null)throw new Exception("Template SCHEDULE OF SLAB title not found.");var full=original.Where(e=>e.Type=="MTEXT"&&Plain(e)=="FULL LENGTH"&&Math.Abs(e.Num(10)-title.Num(10))<400&&Math.Abs(e.Num(20)-title.Num(20))<80).OrderBy(e=>e.Num(10)).ToList();if(full.Count!=2)throw new Exception("Template full-length columns not found.");double left=title.Num(10),top=title.Num(20)-3,dataTop=full[0].Num(20)-7,step=(full[1].Num(10)-full[0].Num(10))/2;double[] x={left,left+25,left+50,left+80,left+110,left+140,left+170,left+200,left+230,left+260,left+290,left+317,left+377};var textPrototype=original.First(e=>e.Type=="MTEXT"&&Regex.IsMatch(Plain(e),@"^\d+S-\d+$")&&e.Num(10)<left+25);var linePrototype=original.First(e=>e.Type=="LINE"&&Math.Abs(e.Num(10)-left)<.01&&Math.Abs(e.Num(20)-top)<.01);var output=new List<Entity>();long next=1;foreach(var e in drawing.Records){long handle;if(long.TryParse(e.Get(5),NumberStyles.HexNumber,CultureInfo.InvariantCulture,out handle))next=Math.Max(next,handle+1);}Action<Entity> add=e=>{e.P.RemoveAll(p=>p.Code==5||p.Code==102);e.Set(5,(next++).ToString("X"));output.Add(e);};Action<double,double,double,double> line=(a,b,c,d)=>{var e=linePrototype.Copy(true);e.Set(10,a);e.Set(20,b);e.Set(11,c);e.Set(21,d);add(e);};Action<string,double,double,double,double,bool> text=(value,a,b,width,height,bold)=>{var e=textPrototype.Copy(true);e.P.RemoveAll(p=>p.Code==1||p.Code==3);e.Set(1,value);e.Set(10,a);e.Set(20,b);e.Set(40,height);e.Set(41,width);e.Set(71,"5");e.Set(7,bold?"A 2.50B":"A 2.0");add(e);};
 foreach(var hatch in original.Where(e=>e.Type=="HATCH")){var xs=new List<double>();var ys=new List<double>();bool boundary=false;foreach(var pair in hatch.P){if(pair.Code==92)boundary=true;if(pair.Code==97)boundary=false;double value;if(boundary&&double.TryParse(pair.Value,NumberStyles.Float,CultureInfo.InvariantCulture,out value)){if(pair.Code==10)xs.Add(value);if(pair.Code==20)ys.Add(value);}}if(xs.Count>=4&&ys.Count>=4&&xs.Min()>=left-.1&&xs.Max()<=x[11]+.1&&ys.Min()>=dataTop-.1&&ys.Max()<=top+.1){var copy=hatch.Copy(true);copy.Set(71,"0");add(copy);}}
 foreach(var e in original.Where(e=>e.Type=="MTEXT"&&e.Num(10)>=left-.01&&e.Num(10)<=x[11]+.01&&e.Num(20)>dataTop&&e.Num(20)<top+18)){var copy=e.Copy(true);if(Plain(e).Contains("SECOND FLOOR")){copy.P.RemoveAll(p=>p.Code==1||p.Code==3);copy.Set(1,"{\\fArial|b1|i0|c0|p34;"+floor.Trim().Replace("\\","").Replace("{","").Replace("}","")+"}");}add(copy);}
 Action<string,double,bool> reference=(value,y,bold)=>{var e=textPrototype.Copy(true);e.P.RemoveAll(p=>p.Code==1||p.Code==3);e.Set(1,value);e.Set(10,x[11]+5);e.Set(20,y);e.Set(40,bold?2.5:1.8);e.Set(41,60);e.Set(71,"4");e.Set(7,bold?"A 2.50B":"A 2.0");add(e);};reference("ORIGINAL SLAB MARKS",(top+dataTop)/2,true);double bottom=dataTop;foreach(var g in groups){double height=Math.Max(7,Math.Ceiling(g.Originals.Length/45.0)*2.5+2);double center=bottom-height/2;text(g.Mark,(x[0]+x[1])/2,center,23,2,false);text(g.Schedule.Thickness.ToString("0.##",CultureInfo.InvariantCulture)+"mm",(x[1]+x[2])/2,center,23,2,false);for(int c=0;c<9;c++)text(BarText(g.Schedule.Bars[c]),(x[c+2]+x[c+3])/2,center,27,2,false);reference(g.Originals,center,false);line(x[0],bottom,x[11],bottom);bottom-=height;}line(x[0],bottom,x[11],bottom);line(x[0],top,x[11],top);line(x[2],top-7,x[10],top-7);line(x[2],top-14,x[10],top-14);for(int c=0;c<x.Length-1;c++){double begin=new[]{3,5,7,9}.Contains(c)?top-14:new[]{4,8}.Contains(c)?top-7:top;line(x[c],begin,x[c],bottom);}
 int start=drawing.Records.FindIndex(e=>e.Type=="SECTION"&&e.Get(2)=="ENTITIES"),end=start+1;while(drawing.Records[end].Type!="ENDSEC")end++;drawing.Records.RemoveRange(start+1,end-start-1);drawing.Records.InsertRange(start+1,output);foreach(var e in drawing.Records)for(int n=0;n<e.P.Count-1;n++)if(e.P[n].Code==9&&e.P[n].Value=="$HANDSEED")e.P[n+1].Value=next.ToString("X");return new SlabFormatResult{Drawing=drawing,Groups=groups,SourceCount=source.Count};}
 public static void Export(SlabFormatResult result,string path){string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{result.Drawing.Write(temp);var rows=ReadRevised(Dxf.Read(temp));if(rows.Count!=result.Groups.Count)throw new Exception("Export verification failed.");for(int n=0;n<rows.Count;n++)if(rows[n].Mark!=result.Groups[n].Mark||Signature(rows[n])!=Signature(result.Groups[n].Schedule))throw new Exception("Slab schedule changed during export.");File.Copy(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static List<SlabScheduleRow> ReadRevised(Dxf drawing){var texts=drawing.ModelEntities().Where(e=>e.Type=="MTEXT"||e.Type=="TEXT").ToList();var full=texts.Where(e=>Plain(e)=="FULL LENGTH").OrderBy(e=>e.Num(10)).ToList();if(full.Count!=2)throw new Exception("Expected two full-length headers in revised slab schedule.");double first=full[0].Num(10),step=(full[1].Num(10)-first)/2;var marks=texts.Where(e=>Regex.IsMatch(Plain(e),@"^[A-Z0-9]*S-\d{3,}$")).OrderByDescending(e=>e.Num(20)).ToList();var result=new List<SlabScheduleRow>();foreach(var mark in marks){var cells=texts.Where(e=>Math.Abs(e.Num(20)-mark.Num(20))<step/10).ToList();var thickness=cells.Where(e=>e.Num(10)>mark.Num(10)&&e.Num(10)<first-step/2).ToList();if(thickness.Count!=1)throw new Exception("Missing/ambiguous slab thickness: "+Plain(mark));double depth;if(!double.TryParse(Plain(thickness[0]).Replace("mm",""),NumberStyles.Float,CultureInfo.InvariantCulture,out depth)||depth<=0)throw new Exception("Invalid slab thickness.");var bars=new SlabBar[9];for(int c=0;c<9;c++){var match=cells.Where(e=>Math.Abs(e.Num(10)-(first+c*step))<step*.4).ToList();if(match.Count!=1)throw new Exception("Missing/ambiguous revised reinforcement: "+Plain(mark));bars[c]=SlabBar.Parse(Plain(match[0]).Replace("mm",""));}if(result.Any(r=>r.Mark==Plain(mark)))throw new Exception("Duplicate revised slab mark.");result.Add(new SlabScheduleRow{Mark=Plain(mark),Thickness=depth,Bars=bars});}if(result.Count==0)throw new Exception("No revised slab marks found.");return result;}
}
}
